#!/usr/bin/env bash
# Squash-merge Zen upstream into this repo, leaving the result uncommitted.
#
# Zen's history is never merged in, because it carries about 6 GB of Windows
# build artifacts from 2024 that would have to be pushed along with it.
# Instead .zen-sync-base records the last Zen commit synced, and a temporary
# local graft makes that commit a second parent of HEAD so git uses it as the
# merge base.
#
# Conflicts in src/**/*.patch resolve to Zen's side automatically. Those
# patches are regenerated by export-patches.sh, which starts from Zen's own, so
# Enso's side of them carries nothing worth keeping. Any other conflict is an
# Enso change to a Zen file and needs resolving by hand.
#
# Then run integrate.sh, build, and `git commit`. Committing only after
# integrating means the sync commit carries the regenerated patches, so no
# commit in history pairs new Zen with stale Glide patches.
#
# Tracks zen/dev. Set ZEN_BRANCH to follow another branch.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source "$ROOT/scripts/enso/lib.sh"

git_root() { git -C "$ROOT" "$@"; }

[ -z "$(git_root status --porcelain --untracked-files=no)" ] \
  || { echo "commit or stash local changes first" >&2; exit 1; }

git_root fetch --quiet zen
base=$(zen_ref)
target=$(git_root rev-parse "zen/$ZEN_BRANCH")

if [ "$base" = "$target" ]; then
  echo "already up to date with zen/$ZEN_BRANCH"
  exit 0
fi

git_root merge-base --is-ancestor "$base" "$target" || {
  echo "zen/$ZEN_BRANCH does not contain $base, so Zen has probably rewritten its history." >&2
  echo "Record the zen/$ZEN_BRANCH commit with the same tree in .zen-sync-base, commit, and re-run:" >&2
  echo "  git log --format='%H %T' zen/$ZEN_BRANCH | grep $(git_root rev-parse "$base^{tree}")" >&2
  exit 1
}

before=$(jq -r .version.version "$ROOT/surfer.json")
msg=$(git_root rev-parse --path-format=absolute --git-path SQUASH_MSG)
rm -f "$msg"

head=$(git_root rev-parse HEAD)
# Silenced because git warns that the replacement drops HEAD's signature,
# which is irrelevant for an object deleted straight after the merge.
# shellcheck disable=SC2046
git_root replace --force --graft "$head" $(git_root rev-parse "$head^@") "$base" 2>/dev/null \
  || { echo "could not graft $base onto HEAD" >&2; exit 1; }
trap 'git_root replace -d "$head" >/dev/null 2>&1 || true' EXIT

# A conflicted merge exits non-zero too, so judge whether it ran by SQUASH_MSG.
git_root merge --squash --quiet "$target" || true
git_root replace -d "$head" >/dev/null
trap - EXIT
[ -f "$msg" ] || { echo "merge of zen/$ZEN_BRANCH did not start; see git's message above" >&2; exit 1; }

resolved=0
while IFS= read -r path; do
  if git_root cat-file -e ":3:$path" 2>/dev/null; then
    git_root checkout --theirs -- "$path"
    git_root add -- "$path"
  else
    git_root rm --quiet -- "$path"
  fi
  resolved=$((resolved + 1))
done < <(git_root diff --name-only --diff-filter=U -- ':(glob)src/**/*.patch')

echo "$target" > "$ROOT/.zen-sync-base"
git_root add .zen-sync-base

after=$(jq -r .version.version "$ROOT/surfer.json")

{
  echo "build: sync Zen to $(git_root rev-parse --short "$target") (Firefox $after)"
  echo
  echo "Squashes these zen/$ZEN_BRANCH commits:"
  echo
  git_root log --format='%h %s' "$base..$target"
} > "$msg"

echo "squash-merged zen/$ZEN_BRANCH at $(git_root rev-parse --short "$target"), uncommitted"
echo "  Firefox $before -> $after"
echo "  $resolved patch conflict(s) resolved to Zen's side"

remaining=$(git_root diff --name-only --diff-filter=U)
if [ -n "$remaining" ]; then
  echo "  resolve these by hand and stage them:"
  sed 's/^/    /' <<< "$remaining"
fi

echo
echo "next: bash scripts/enso/integrate.sh, build, then git commit"
